        menu_addlink("Kick players", menu_in_game_menu_kick_players);
    }
    menu_addlink("Options", menu_in_game_menu_options);
    menu_addlink("Disconnect", menu_in_game_menu_disconnect);
    menu_addlink("Quit Game", menu_in_game_menu_quit_game);
}
